function c(t){const r=Number(t);return!Number.isFinite(r)||r<=0?0:Math.floor(r)}function n(t,r){const e=c(r);if(e<=0)return null;const s=Number.isFinite(t)?Math.max(0,t):0;return s>=e?100:Math.round(s/e*1e3)/10}function o(t,r){const e=c(r);if(e<=0)return null;const s=Number.isFinite(t)?t:0;return s<=0?"out_of_stock":s>=e?"healthy":s/e<.5?"critical":"low_stock"}function a(t,r=!1){if(!t)return"—";if(!r)switch(t){case"healthy":return"Healthy";case"low_stock":return"Low Stock";case"critical":return"Critical";case"out_of_stock":return"Out of Stock"}switch(t){case"healthy":return"سليم";case"low_stock":return"مخزون منخفض";case"critical":return"حرج";case"out_of_stock":return"نفد المخزون"}}function u(t){switch(t){case"healthy":return"bg-status-success-fg";case"low_stock":return"bg-status-warning-fg";case"critical":case"out_of_stock":return"bg-status-danger-fg";default:return"bg-border-strong"}}export{n as a,a as b,u as c,o as s};
